/** 指定难度下指定关卡的 Boss 索引（每 3 关轮换池内形态，50 关循环；参数缺省取当前状态） */
G.levelBossIndex = function (lv, diff) {
  const d = diff || G.difficultyMode || 'normal';
  const pool = G.BOSS_POOLS[d] || G.BOSS_POOLS.normal;
  const level = lv || G.level || 1;
  return pool[Math.floor((level - 1) / 3) % pool.length];
};

