// ---------- 每关词表：开局随机抽 20 个，本关内循环重复；每局/每关重新抽取 ----------
G.STAGE_WORD_COUNT = 20;
G.stageWords = [];
G.stageWordIdx = 0;
// 跨关去重池：本局已出现过的单词（含填充词），新一局清空
G.usedWordEns = new Set();
G.resetUsedWords = function () { G.usedWordEns.clear(); };

function shuffleArr (arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const t = arr[i]; arr[i] = arr[j]; arr[j] = t;
  }
  return arr;
}

G.initStageWords = function () {
  // 优先抽取本局尚未用过的词，保证每关单词不重复；池子枯竭时回退全库
  const fresh = G.WORDS.filter(w => !G.usedWordEns.has(w.en));
  const pool = shuffleArr(fresh.length >= G.STAGE_WORD_COUNT ? fresh : G.WORDS.slice());
  G.stageWords = pool.slice(0, Math.min(G.STAGE_WORD_COUNT, pool.length));
  for (const w of G.stageWords) G.usedWordEns.add(w.en);
  G.stageWordIdx = 0;
  // 本关词汇击打记录（通关结算词汇表用：en -> {en, cn, pos, hit}）
  G.stageWordHits = new Map();
  for (const w of G.stageWords) {
    G.stageWordHits.set(w.en, { en: w.en, cn: w.cn, pos: G.WORD_POS[w.en] || '', hit: false });
  }
  // 长短分流：优先从本关 20 词中挑，数量不足则优先用本局未出现过的词补充
  // （补充池同样耗尽时才允许使用已出现过的词，保证两类都够用）
  const shorts = G.stageWords.filter(w => w.en.length <= G.SHORT_MAX);
  const longs = G.stageWords.filter(w => w.en.length >= G.LONG_MIN);
  const shortPool = G.WORDS.filter(w => w.en.length <= G.SHORT_MAX);
  const longPool = G.WORDS.filter(w => w.en.length >= G.LONG_MIN);
  const fill = (arr, src, min) => {
    const inArr = new Set(arr.map(a => a.en));
    let rest = shuffleArr(src.filter(w => !inArr.has(w.en) && !G.usedWordEns.has(w.en)));
    if (rest.length < min - arr.length) {
      rest = rest.concat(shuffleArr(src.filter(w => !inArr.has(w.en) && G.usedWordEns.has(w.en))));
    }
    while (arr.length < min && rest.length) {
      const w = rest.pop();
      arr.push(w); inArr.add(w.en); G.usedWordEns.add(w.en);
    }
  };
  fill(shorts, shortPool, 10);
  fill(longs, longPool, 8);
  G.shortWords = shorts;
  G.longWords = longs;
  G.shortIdx = 0;
  G.longIdx = 0;
};
G.nextStageWord = function () {
  if (!G.stageWords || G.stageWords.length === 0) G.initStageWords();
  const w = G.stageWords[G.stageWordIdx % G.stageWords.length];
  G.stageWordIdx++;
  return w;
};

/** 击杀携带该词的敌机时调用：标记本关该词为“已击打”（结算词汇表用） */
G.markWordHit = function (en) {
  const r = G.stageWordHits && G.stageWordHits.get(en);
  if (r) r.hit = true;
};

// ---------- 长短单词分流 ----------
// 跑得偏快的敌人（侦察/自爆/狙击/分裂）只携带短单词；
// 长单词单独由「诗抄机」携带，并在攻击形态逐字发射单词拼写。
G.SHORT_MAX = 5;    // 短单词长度上限（字母数）
G.LONG_MIN = 8;     // 长单词长度下限（字母数）
G.shortWords = [];
G.longWords = [];
G.shortIdx = 0;
G.longIdx = 0;
G.nextShortWord = function () {
  if (!G.shortWords.length) G.initStageWords();
  const w = G.shortWords[G.shortIdx % G.shortWords.length];
  G.shortIdx++;
  return w;
};
G.nextLongWord = function () {
  if (!G.longWords.length) G.initStageWords();
  const w = G.longWords[G.longIdx % G.longWords.length];
  G.longIdx++;
  return w;
};

